import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("a single sword → base premium 100 G, premium 115 G (100 + 10 first insurance + 5 fee)");
    it.todo("a single amulet → base premium 60 G, premium 71 G (60 + 6 + 5)");
    it.todo("a single staff → base premium 80 G, premium 93 G (80 + 8 + 5)");
    it.todo("a single potion → base premium 40 G, premium 49 G (40 + 4 + 5)");
    it.todo("a single rune (component) → base premium 25 G, premium 33 G (25 + 2.5 + 5, rounded up)");
    it.todo("a single moonstone (component) → base premium 25 G");
  });

  describe("building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("premium modifiers", () => {
    it.todo("cursed sword adds a 50 % risk surcharge of the item's base premium");
    it.todo("sword with enchantment 5 → high-enchantment surcharge of 30 % applies");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge");
    it.todo("cursed sword with enchantment 5 → both surcharges apply");
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("a first insurance carries a 10 % initial assessment surcharge");
    it.todo("the second quote in a scenario receives a 15 % follow-up contract discount");
    it.todo("a 5 G processing fee is added to every premium");
  });

  describe("modifier scope on multi-item policies", () => {
    it.todo("cursed sword (100 G) + plain amulet (60 G) → policy base 160 G, curse adds 50 G → 210 G before further modifiers and fee");
    it.todo("policy-wide modifiers apply to the sum of all item base premiums, the fee is added last");
  });

  describe("rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
    it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");
  });

  describe("claim processing — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");
  });

  describe("claim processing — special clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (the 50 % rule wins)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("deductible per damage event", () => {
    it.todo("a dragon attack damages an insured sword (500 G) and an insured amulet (300 G) → payout 600 G (deductible once per damaged item)");
  });

  describe("multiple items of the same type", () => {
    it.todo("a policy covers two swords → insurance sum 2000 G, cap 4000 G");
    it.todo("two sword damage entries against a two-sword policy → each treated as a separate damage with its own deductible");
    it.todo("more damage entries of a type than insured (two sword damages, one sword insured) → error, non-zero exit");
  });

  describe("cap exhaustion", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a cursed sword (premium 165 G) → cap 2000 G (based on the unmodified insurance value)");
    it.todo("a policy covering a sword and 3 runes (a block) → insurance sum 1750 G (block discount affects the premium only)");
    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword policy, second claim of 1500 G after the first → payout 600 G, remainingCap 0 G");
  });

  describe("integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G");
    it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
  });

  describe("error cases", () => {
    it.todo("quote includes an item with an unknown type (broomstick) → error");
    it.todo("claim references a damage entry whose item is not part of the policy (amulet damaged, only sword insured) → error");
    it.todo("claim references a damage entry with an unknown item type → error");
    it.todo("claim contains a damage entry with amount: -200 → error");
  });

  describe("CLI", () => {
    it.todo("reads a scenario from stdin and writes {results: [...]} to stdout in step order");
    it.todo("the schema example scenario yields a premium result and a payout/remainingCap result");
    it.todo("an invalid scenario exits with a non-zero status code, writes to stderr and no results to stdout");
  });
});

