50	const addPercent = (amount: number, percent: number): number =>
51	  amount + (amount * percent) / 100;
52	
53	/** Rounds up — premiums round in the MHPCO's favour. */
54	const roundPremium = (amount: number): number => Math.ceil(amount);
55	
56	const itemBasePremium = (): number => SWORD_BASE_PREMIUM;
57	
