const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

/** Percentages are applied as integer arithmetic so that the final
 *  rounding is not corrupted by float artifacts (100 * 1.1 === 110.000…1). */
const addPercent = (amount: number, percent: number): number =>
  amount + (amount * percent) / 100;

/** Rounds up — premiums round in the MHPCO's favour. */
const roundPremium = (amount: number): number => Math.ceil(amount);

const itemBasePremium = (item: Item): number =>
  BASE_PREMIUM_BY_TYPE[item.type];

const policyBasePremium = (items: Item[]): number =>
  items.reduce((total, item) => total + itemBasePremium(item), 0);

const quote = (items: Item[]): QuoteResult => {
  const basePremium = policyBasePremium(items);
  const modifiedPremium = addPercent(
    basePremium,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );
  // The processing fee is added last, after all percentage modifiers.
  const premium = modifiedPremium + PROCESSING_FEE;
  return { premium: roundPremium(premium) };
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quote(step.items);
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map(runStep);
  return { results };
};

