export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: { cause: string; damages: Damage[] };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioResult {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

/** Percentages are applied as integer arithmetic so that the final
 *  rounding is not corrupted by float artifacts (100 * 1.1 === 110.000…1). */
const addPercent = (amount: number, percent: number): number =>
  amount + (amount * percent) / 100;

/** Rounds up — premiums round in the MHPCO's favour. */
const roundPremium = (amount: number): number => Math.ceil(amount);

const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_BASE_PREMIUM = 60;

const COMPONENT_TYPES = ["rune", "moonstone"];

const isComponent = (item: Item): boolean =>
  COMPONENT_TYPES.includes(item.type);

const itemBasePremium = (item: Item): number =>
  BASE_PREMIUM_BY_TYPE[item.type];

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

/** A block is exactly three alike components, priced as a unit rather than
 *  per item. Larger counts do not decompose into blocks: 7 runes cost 7 × 25. */
const componentGroupBasePremium = ([type, count]: [string, number]): number =>
  count === COMPONENT_BLOCK_SIZE
    ? COMPONENT_BLOCK_BASE_PREMIUM
    : count * BASE_PREMIUM_BY_TYPE[type];

const sum = (amounts: number[]): number =>
  amounts.reduce((total, amount) => total + amount, 0);

const policyBasePremium = (items: Item[]): number => {
  const mainItems = items.filter((item) => !isComponent(item));
  const componentGroups = [...countByType(items.filter(isComponent))];

  return (
    sum(mainItems.map(itemBasePremium)) +
    sum(componentGroups.map(componentGroupBasePremium))
  );
};

const quote = (items: Item[]): QuoteResult => {
  const basePremium = policyBasePremium(items);
  const modifiedPremium = addPercent(
    basePremium,
    FIRST_INSURANCE_SURCHARGE_PERCENT,
  );
  // The processing fee is added last, after all percentage modifiers.
  const premium = modifiedPremium + PROCESSING_FEE;
  return { premium: roundPremium(premium) };
};

const runStep = (step: Step): StepResult => {
  if (step.op === "quote") return quote(step.items);
  throw new Error(`Unsupported step: ${step.op}`);
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const results = scenario.steps.map(runStep);
  return { results };
};

